describe('Checkbox States - Toggle Behavior', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
  });

  it('should toggle checkbox states correctly when interacting with the first checkbox', () => {
    // Verify initial state
    cy.get('[data-testid="checkbox-1"]').should('not. be checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');

    // Check the first checkbox
    cy.get('[data-testid="checkbox-1"]').click();
    cy.get('[data-testid="checkbox-1"]').should('be. checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');

    // Uncheck the first checkbox
    cy.get('[data-testid="checkbox-1"]').click();
    cy.get('[data-testid="checkbox-1"]').should('not. be checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');

    // Check the first checkbox again
    cy.get('[data-testid="checkbox-1"]').click();
    cy.get('[data-testid="checkbox-1"]').should('be. checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');
  });

  it('should maintain correct state when unchecking the second checkbox', () => {
    // Verify initial state
    cy.get('[data-testid="checkbox-1"]').should('not. be checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');

    // Check the first checkbox
    cy.get('[data-testid="checkbox-1"]').click();
    cy.get('[data-testid="checkbox-1"]').should('be. checked');
    cy.get('[data-testid="checkbox-2"]').should('be. checked');

    // Uncheck the second checkbox
    cy.get('[data-testid="checkbox-2"]').click();
    cy.get('[data-testid="checkbox-2"]').should('not. be checked');
    cy.get('[data-testid="checkbox-1"]').should('be. checked');

    // Check the second checkbox again
    cy.get('[data-testid="checkbox-2"]').click();
    cy.get('[data-testid="checkbox-2"]').should('be. checked');
    cy.get('[data-testid="checkbox-1"]').should('be. checked');
  });
});
